-- Germany wave 3: the 1,583 Einzellagen — the individual vineyard sites of the
-- Rheinland-Pfalz Weinbergsrolle, and the level German wine labels actually name.
--
-- These are SITE nodes at tier 4, the same kind France uses for Burgundy climats.
-- Unlike every tier above them, their boundaries are NOT dissolved or
-- generalised: the Weinbergsrolle polygon IS the legal site, used as-is.
--
-- Keys include the village because Lage names are heavily reused — 1,010
-- distinct names across 1,583 sites (Schloßberg x43, Sonnenberg x37). Where
-- village+name still collides, the official wlg_nr disambiguates. wlg_nr is
-- unique across all 1,583 and is the stable source_feature_id.
--
-- Generated by .tiles-build/gen-einzellagen-migration.mjs.
-- Nodes land DRAFT; build-germany-einzellagen.mjs attaches geometry + promotes.

begin;

create temp table _e (parent text, slug text, name text, village text, nr text, flaeche text) on commit drop;





  slug, canonical_key, name, kind, display_tier, min_zoom, label_min_zoom,
  is_appellation, appellation_system, appellation_level,
  publication_status, sort_order, primary_parent_id
)
select e.slug, e.parent || '.' || e.slug, e.name, 'SITE', 4, 9, 10,
       true, 'g.U.', 'communal', 'DRAFT', 0, p.id
  from _e e
  join wine_places p on p.canonical_key = e.parent
 where not exists (select 1 from wine_places x where x.canonical_key = e.parent || '.' || e.slug);

select p.id,
  'An Einzellage — a single, legally delimited vineyard site in ' || e.village ||
  ', registered in the Weinbergsrolle as no. ' || e.nr ||
  '. This is the most precise origin a German label can name, and unlike a Großlage it refers to one defined piece of ground.',
  array['Einzellage — a single vineyard site', 'Village: ' || e.village, 'Weinbergsrolle no. ' || e.nr]::text[],
  'PUBLISHED'
from _e e
join wine_places p on p.canonical_key = e.parent || '.' || e.slug
where not exists (select 1 from wine_place_articles a where a.wine_place_id = p.id);

do $$
declare v int;
begin
  select count(*) into v from wine_places where canonical_key like 'germany.%' and display_tier = 4;
  if v <> 1583 then raise exception 'expected 1583 Einzellagen, got %', v; end if;
end $$;

commit;
